xpath.script:
(function(){
  "use strict";
  // Solo actuar en la página del carrito
  if (!/\/shop\/cart\b/.test(location.pathname)) return;

  function $(s,r){return (r||document).querySelector(s);}
  function $all(s,r){return Array.from((r||document).querySelectorAll(s));}

  function getLineId(line){
    if (!line) return null;
    var v = line.getAttribute("data-line-id"); if (v) return v;
    var inp = $('input[name="line_id"]', line); if (inp && inp.value) return inp.value;
    var a = $('a[href*="line_id="]', line);
    if (a){
      try {
        var u = new URL(a.getAttribute('href'), location.origin);
        var lid = u.searchParams.get('line_id'); if (lid) return lid;
      } catch(_){}
    }
    return null;
  }

  function getDescBox(line){
    return $('.o_wsale_product_information', line)
        || $('.o_wsale_cart_description', line)
        || $('.media-body', line)
        || $('.product_text', line)
        || line;
  }

  function colorFromText(line){
    try{
      var txt = getDescBox(line).innerText || '';
      var m = txt.match(/#([0-9A-Fa-f]{6})/);
      return m ? ('#'+m[1].toUpperCase()) : null;
    }catch(_){ return null; }
  }

  function ensurePreview(line){
    var id = getLineId(line);
    if (!id) return;

    // Elimina cualquier preview previo SOLO dentro de esta línea
    $all('.spw-cart-preview[data-line="'+id+'"]', line).forEach(function(n){ n.remove(); });

    var wrap = document.createElement('div');
    wrap.className = 'spw-cart-preview';
    wrap.setAttribute('data-line', id);

    // Píldora de color (si conseguimos un HEX del texto)
    var hex = colorFromText(line);
    if (hex){
      var pill = document.createElement('span');
      pill.className = 'spw-color-pill';
      pill.title = hex;
      pill.style.background = hex;
      wrap.appendChild(pill);
    }

    // Miniatura generada por el backend
    var img = new Image();
    img.alt = "Personalización";
    img.loading = "lazy";
    img.src = "/spw/line_preview/"+encodeURIComponent(id)+".png?_="+(Date.now()%100000);
    wrap.appendChild(img);

    var desc = getDescBox(line);
    if (desc) desc.appendChild(wrap); else line.appendChild(wrap);
  }

  function injectAll(){
    var lines = $all('.js_cart_lines .row, tr.js_cart_line, .o_wsale_cart_item, .card.js_cart_item');
    if (!lines.length) lines = $all('[data-line-id]');
    lines.forEach(ensurePreview);
  }

  // Primera pasada
  injectAll();

  // Reinyectar si Odoo re-renderiza al cambiar cantidades
  var root = $('.js_cart_lines') || $('main') || document.body;
  if (window.MutationObserver && root){
    var mo = new MutationObserver(function(){ requestAnimationFrame(injectAll); });
    mo.observe(root, {childList:true, subtree:true});
  }
  // Reintentos suaves por si hay cargas diferidas
  setTimeout(injectAll, 300);
  setTimeout(injectAll, 1200);
})();
